# >>> justin-sdk:ts-check >>> MANAGED BLOCK — regenerated by `bun run justin-sdk add husky`. Edit the SDK template, not this copy.
# Type-check before every commit (home-base-lzvh). A type error refuses the
# commit. To stop it: set componentConfig.husky.tsCheckInHook to false in
# justin-sdk.config.json, so the installer stops adding it, then delete this
# block. componentConfig.husky.tsCheckOnCommit decides whether a commit that
# stages only docs is checked: `bun run justin-sdk pre-commit-ts-check --help`.
# The probe greps the command list because `justin-sdk <unknown> --help` exits
# 0; an SDK from before the command runs the type-check directly.
# TS18003 ("No inputs were found") lets the commit through only when git
# tracks no TypeScript file: then there is nothing to type-check. With
# TypeScript files present it means the include globs are broken, and the
# commit is refused. `justin-sdk signal` draws the same line (home-base-gsqz);
# tsc prints the same text in both cases, so the files decide.
if [ -f tsconfig.json ]; then
  if grep -q '"signal-source:TS"' package.json 2>/dev/null; then
    if bun run justin-sdk --help 2>/dev/null | grep -q 'pre-commit-ts-check'; then
      _jsdk_ts_out=$(bun run justin-sdk pre-commit-ts-check -- bun run signal-source:TS 2>&1) && _jsdk_ts_status=0 || _jsdk_ts_status=$?
    else
      _jsdk_ts_out=$(bun run signal-source:TS 2>&1) && _jsdk_ts_status=0 || _jsdk_ts_status=$?
    fi
    if [ -n "$_jsdk_ts_out" ]; then
      printf '%s\n' "$_jsdk_ts_out"
    fi
    if [ "$_jsdk_ts_status" -ne 0 ]; then
      if ! printf '%s\n' "$_jsdk_ts_out" | grep -q 'TS18003'; then
        exit 1
      elif ! _jsdk_ts_files=$(git ls-files -- '*.ts' '*.tsx' '*.mts' '*.cts'); then
        echo "[pre-commit] Type check refused the commit: TS18003, and git ls-files could not list this repo's TypeScript files to tell whether there are any."
        exit 1
      elif [ -z "$_jsdk_ts_files" ]; then
        echo "[pre-commit] Type check skipped: this repo has no TypeScript files (TS18003), so there is nothing to type-check."
      else
        echo "[pre-commit] Type check failed: tsconfig.json's include matches none of this repo's TypeScript files (TS18003)."
        exit 1
      fi
    fi
    unset _jsdk_ts_out _jsdk_ts_status _jsdk_ts_files
  else
    echo "[pre-commit] Type check skipped: package.json has no \"signal-source:TS\" script."
  fi
fi
# <<< justin-sdk:ts-check <<<
